// MODULO OFICIAL DE REPORTE DIARIO EXCEL (TEKA)
// Generación en navegador 100% fiel a muestra.xlsx
// ==========================================================================

window.MUESTRA_XLSX_BASE64 = "";

// Convertir Base64 a Uint8Array
function b64ToUint8ReporteDiario(base64) {
    const raw = window.atob(base64);
    const rawLength = raw.length;
    const array = new Uint8Array(new ArrayBuffer(rawLength));
    for (let i = 0; i < rawLength; i++) {
        array[i] = raw.charCodeAt(i);
    }
    return array;
}

// Formatear fechas a D/M/YY (ej: 22/9/26 sin ceros iniciales)
function formatFechaDMYY(dateStrOrObj) {
    if (!dateStrOrObj) return '';
    let d;
    if (typeof dateStrOrObj === 'string') {
        const parts = dateStrOrObj.split('-');
        if (parts.length === 3) {
            d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
        } else {
            d = new Date(dateStrOrObj);
        }
    } else {
        d = dateStrOrObj;
    }
    if (isNaN(d.getTime())) return '';
    const day = d.getDate();
    const month = d.getMonth() + 1;
    const yy = String(d.getFullYear()).slice(-2);
    return `${day}/${month}/${yy}`;
}

// Generar horas distribuidas uniformemente entre 09:00 y 17:00
function getDistributedTimesDiario(numItems) {
    if (numItems <= 0) return [];
    if (numItems === 1) return ["09:00"];
    const times = [];
    const startMinutes = 9 * 60; // 09:00
    const totalSpan = 8 * 60;    // 8 horas -> 17:00
    for (let i = 0; i < numItems; i++) {
        const fraction = i / (numItems - 1);
        const currentMinutes = startMinutes + fraction * totalSpan;
        const totalM = Math.round(currentMinutes);
        const hour = Math.floor(totalM / 60);
        const minute = totalM % 60;
        times.push(String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0'));
    }
    return times;
}

// Extraer individualmente cada equipo del cliente con su serie
function extractEquiposVisitDiario(v, isHoy) {
    const results = [];
    
    // 1. Caso de Mantenimiento específico
    if (v.esMantenimiento && v.mantenimientoEquipo) {
        results.push({
            equipo: String(v.mantenimientoEquipo).toUpperCase().trim(),
            serie: isHoy ? String(v.serieEquipo || '').toUpperCase().trim() : 'ABIERTO',
            motivo: 'MANTENIMIENTO PREVENTIVO'
        });
        return results;
    }

    // 2. Desglose de array de equipos
    if (Array.isArray(v.equipos) && v.equipos.length > 0) {
        v.equipos.forEach(eq => {
            if (!eq) return;
            let desc = '';
            let serie = '';
            if (typeof eq === 'object') {
                desc = eq.descProducto || eq.manualName || eq.nombre || '';
                serie = isHoy ? (eq.serieEquipo || eq.serie || '') : 'ABIERTO';
            } else if (typeof eq === 'string') {
                desc = eq;
                serie = isHoy ? (v.serieEquipo || '') : 'ABIERTO';
            }
            desc = desc.toUpperCase().trim();
            if (!desc && v.tipoAtencion) desc = v.tipoAtencion.toUpperCase().trim();
            if (!desc) desc = 'EQUIPO NO ESPECIFICADO';

            // Determinar motivo
            let motivo = 'SOLICITUD INSTALACIÓN';
            const att = (v.tipoAtencion || '').toUpperCase();
            if (att.includes('MANT')) motivo = 'MANTENIMIENTO PREVENTIVO';
            else if (att.includes('GARAN')) motivo = 'SOLICITUD GARANTÍA';
            else if (v.motivo) motivo = v.motivo.toUpperCase().trim();

            results.push({
                equipo: desc,
                serie: isHoy ? String(serie).toUpperCase().trim() : 'ABIERTO',
                motivo: motivo
            });
        });
    }

    // 3. Respaldo si no hay array de equipos
    if (results.length === 0) {
        let desc = (v.mantenimientoEquipo || v.asunto || v.tipoAtencion || 'SOLICITUD INSTALACIÓN').toUpperCase().trim();
        let motivo = 'SOLICITUD INSTALACIÓN';
        if (desc.includes('MANT') || (v.tipoAtencion && v.tipoAtencion.toUpperCase().includes('MANT'))) {
            motivo = 'MANTENIMIENTO PREVENTIVO';
        }
        results.push({
            equipo: desc,
            serie: isHoy ? String(v.serieEquipo || '').toUpperCase().trim() : 'ABIERTO',
            motivo: motivo
        });
    }

    return results;
}

// Construir todas las filas planas del reporte con las 21 columnas
window.buildReporteDiarioData = function() {
    const fechaHoyInput = document.getElementById('repDiarioFechaHoy');
    const fechaAyerInput = document.getElementById('repDiarioFechaAyer');
    const fechaMananaInput = document.getElementById('repDiarioFechaManana');
    const techFilterSelect = document.getElementById('repDiarioTechFilter');

    const hoyStr = (fechaHoyInput ? fechaHoyInput.value : '') || new Date().toISOString().split('T')[0];
    
    // Ayer por defecto
    let defAyer = '';
    const dHoy = new Date(hoyStr + 'T12:00:00');
    const dAyer = new Date(dHoy);
    dAyer.setDate(dHoy.getDate() - 1);
    defAyer = dAyer.toISOString().split('T')[0];

    // Mañana por defecto
    let defManana = '';
    const dManana = new Date(dHoy);
    dManana.setDate(dHoy.getDate() + 1);
    defManana = dManana.toISOString().split('T')[0];

    const ayerStr = (fechaAyerInput && fechaAyerInput.value) ? fechaAyerInput.value : defAyer;
    const mananaStr = (fechaMananaInput && fechaMananaInput.value) ? fechaMananaInput.value : defManana;
    const techFilter = (techFilterSelect ? techFilterSelect.value : 'JUAN CARLOS PANDO').toUpperCase().trim();

    const fechaHoyDMYY = formatFechaDMYY(hoyStr);
    const fechaAyerDMYY = formatFechaDMYY(ayerStr);
    const fechaMananaDMYY = formatFechaDMYY(mananaStr);

    const visits = Array.isArray(window.visitsArray) ? window.visitsArray : [];

    // Filtrar visitas de Hoy y de Mañana
    const visitasHoy = [];
    const visitasManana = [];

    visits.forEach(v => {
        if (!v || typeof v !== 'object') return;
        const vTech = (v.tecnico || '').toUpperCase();
        if (techFilter !== 'TODOS' && !vTech.includes(techFilter)) return;

        const vDate = v.fechaNuevaVisita || v.fechaEntregaProgramada || v.fechaInstalacion || '';
        if (vDate === hoyStr) {
            visitasHoy.push(v);
        } else if (vDate === mananaStr) {
            visitasManana.push(v);
        }
    });

    visitasHoy.sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    visitasManana.sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));

    // Preparar filas para Hoy
    const hoyVisitsRows = [];
    const horasFijas = ["09:00", "11:00", "13:00", "15:00", "17:00"];
    let idxHoraHoy = 0;

    visitasHoy.forEach(v => {
        const horaSolicitud = horasFijas[idxHoraHoy % horasFijas.length];
        idxHoraHoy++;
        const cliente = (v.nombreCliente || '').toUpperCase().trim();
        const telefono = v.telefono || '';
        const direccion = (v.callePrincipal || v.direccion || '').toUpperCase().trim();
        const email = (v.email || '').toUpperCase().trim();
        const tecnico = (v.tecnico || 'JUAN CARLOS PANDO').toUpperCase().trim();
        const eqs = extractEquiposVisitDiario(v, true);

        const rowsThisVisit = eqs.map(item => ({
            fecha_solicitud: fechaAyerDMYY,
            hora_solicitud: horaSolicitud,
            fecha_contacto: fechaAyerDMYY,
            hora_contacto: horaSolicitud,
            fecha_cierre: fechaHoyDMYY,
            motivo: item.motivo,
            equipo: item.equipo,
            serie: item.serie,
            cliente: cliente,
            telefono: telefono,
            direccion: direccion,
            tecnico: tecnico,
            fecha_primera_visita: fechaHoyDMYY,
            resuelto: 'ATENDIDO',
            pendiente: 'NO',
            canal: 'LLAMADA DIRECTA',
            estado: 'ATENDIDO',
            email: email,
            isHoy: true,
            visitId: v.id || ''
        }));
        hoyVisitsRows.push(rowsThisVisit);
    });

    // Horarios distribuidos para Hoy
    const flatHoyCount = hoyVisitsRows.reduce((acc, cur) => acc + cur.length, 0);
    const timesHoy = getDistributedTimesDiario(flatHoyCount);

    const finalRowsHoy = [];
    let flatIdxHoy = 0;
    hoyVisitsRows.forEach(visitGroup => {
        const horaVisita = timesHoy[flatIdxHoy] || '09:00';
        visitGroup.forEach(r => {
            r.horario_visita = horaVisita;
            finalRowsHoy.push(r);
            flatIdxHoy++;
        });
    });

    // Preparar filas para Mañana
    const mananaVisitsRows = [];
    let baseTimeMinutes = 8 * 60 + 35; // 08:35 AM

    visitasManana.forEach(v => {
        const h = Math.floor(baseTimeMinutes / 60);
        const m = baseTimeMinutes % 60;
        const horaSolicitud = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');

        // Escalonar entre 35 y 65 minutos para la siguiente solicitud (tope 17:00)
        baseTimeMinutes = Math.min(17 * 60, baseTimeMinutes + 45);

        const cliente = (v.nombreCliente || '').toUpperCase().trim();
        const telefono = v.telefono || '';
        const direccion = (v.callePrincipal || v.direccion || '').toUpperCase().trim();
        const email = (v.email || '').toUpperCase().trim();
        const tecnico = (v.tecnico || 'JUAN CARLOS PANDO').toUpperCase().trim();
        const eqs = extractEquiposVisitDiario(v, false);

        const rowsThisVisit = eqs.map(item => ({
            fecha_solicitud: fechaHoyDMYY,
            hora_solicitud: horaSolicitud,
            fecha_contacto: fechaHoyDMYY,
            hora_contacto: horaSolicitud,
            fecha_cierre: 'ABIERTO',
            motivo: item.motivo,
            equipo: item.equipo,
            serie: 'ABIERTO',
            cliente: cliente,
            telefono: telefono,
            direccion: direccion,
            tecnico: tecnico,
            fecha_primera_visita: fechaMananaDMYY,
            horario_visita: 'ABIERTO',
            resuelto: 'ABIERTO',
            pendiente: 'NO',
            canal: 'LLAMADA DIRECTA',
            estado: 'ABIERTO',
            email: email,
            isHoy: false,
            visitId: v.id || ''
        }));
        mananaVisitsRows.push(rowsThisVisit);
    });

    const finalRowsManana = [];
    mananaVisitsRows.forEach(visitGroup => {
        visitGroup.forEach(r => {
            finalRowsManana.push(r);
        });
    });

    const allRows = [...finalRowsHoy, ...finalRowsManana];

    // Mapear a estructura de 22 celdas de muestra.xlsx (Col A vacía, Cols B a V)
    const excelReadyRows = allRows.map(r => {
        const rowData = [
            '',                          // Col A (vacía)
            r.fecha_solicitud,           // Col B: Fecha solicitud
            r.hora_solicitud,            // Col C: HORA DE SOLICITUD
            r.fecha_contacto,            // Col D: Fecha contacto con cliente
            r.hora_contacto,             // Col E: HORA DE PRIMER CONTACTO CON CLIENTE
            r.fecha_cierre,              // Col F: Fecha cierre del trabajo
            r.motivo,                    // Col G: motivo de llamada
            r.equipo,                    // Col H: Equipo
            r.serie,                     // Col I: serie
            r.cliente,                   // Col J: Cliente
            r.telefono,                  // Col K: telefono de cliente
            r.direccion,                 // Col L: dirección
            r.tecnico,                   // Col M: Técnico que asiste
            r.fecha_primera_visita,      // Col N: fecha de Primera visita (Sí/No)
            r.horario_visita,            // Col O: horario de visita
            '',                          // Col P: Satisfacción (1-5)
            '',                          // Col Q: Costo
            r.resuelto,                  // Col R: resuelto en primera llamada
            r.pendiente,                 // Col S: pendiente por repuesto
            r.canal,                     // Col T: como llego la información
            r.estado,                    // Col U: Estado
            r.email                      // Col V: CORREO DE CLIENTE
        ];
        return {
            cells: rowData,
            raw: r
        };
    });

    return {
        visitasHoyCount: visitasHoy.length,
        equiposHoyCount: finalRowsHoy.length,
        visitasMananaCount: visitasManana.length,
        equiposMananaCount: finalRowsManana.length,
        totalFilas: excelReadyRows.length,
        rows: excelReadyRows,
        fechaHoyDMYY,
        fechaAyerDMYY,
        fechaMananaDMYY,
        hoyStr,
        mananaStr
    };
};

// Generar y descargar el archivo Excel
window.descargarReporteDiarioExcel = async function() {
    if (typeof ExcelJS === 'undefined') {
        alert('La librería ExcelJS no está cargada en la página.');
        return;
    }

    const btn = document.getElementById('btnDescargarReporteDiario');
    const originalText = btn ? btn.innerHTML : '';
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '⏳ GENERANDO ARCHIVO EXCEL...';
    }

    try {
        const data = window.buildReporteDiarioData();
        if (data.rows.length === 0) {
            alert('No hay visitas encontradas para las fechas y técnico seleccionados.');
            if (btn) { btn.disabled = false; btn.innerHTML = originalText; }
            return;
        }

        const wb = new ExcelJS.Workbook();
        const buffer = b64ToUint8ReporteDiario(window.MUESTRA_XLSX_BASE64);
        await wb.xlsx.load(buffer);

        const sheet = wb.worksheets[0];

        // Añadir las filas de datos con formato profesional
        data.rows.forEach(r => {
            const excelRow = sheet.addRow(r.cells);
            excelRow.height = 22;

            excelRow.eachCell({ includeEmpty: true }, (cell, colNumber) => {
                if (colNumber < 2 || colNumber > 22) return;

                cell.font = {
                    name: 'Aptos Narrow',
                    size: 10,
                    bold: false,
                    color: { argb: 'FF1E293B' }
                };

                // Alineación: textos descriptivos a la izquierda, el resto centrado
                const isTextCol = (colNumber === 10 || colNumber === 12 || colNumber === 22 || colNumber === 8);
                cell.alignment = {
                    vertical: 'middle',
                    horizontal: isTextCol ? 'left' : 'center',
                    wrapText: colNumber === 12 || colNumber === 8
                };

                // Bordes suaves
                cell.border = {
                    top: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                    left: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                    bottom: { style: 'thin', color: { argb: 'FFE2E8F0' } },
                    right: { style: 'thin', color: { argb: 'FFE2E8F0' } }
                };

                // Resaltar suavemente el estado
                if (colNumber === 21) { // Col U: Estado
                    if (cell.value === 'ATENDIDO') {
                        cell.font = { name: 'Aptos Narrow', size: 10, bold: true, color: { argb: 'FF065F46' } };
                        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD1FAE5' } };
                    } else if (cell.value === 'ABIERTO') {
                        cell.font = { name: 'Aptos Narrow', size: 10, bold: true, color: { argb: 'FF1E40AF' } };
                        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDBEAFE' } };
                    }
                }
            });
        });

        const outBuffer = await wb.xlsx.writeBuffer();
        const blob = new Blob([outBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');

        // Nombre de archivo sugerido
        const fileNameInput = document.getElementById('repDiarioFileName');
        let customName = fileNameInput ? fileNameInput.value.trim() : '';
        if (!customName) {
            const fechaClean = data.fechaHoyDMYY.replace(/\//g, '-');
            customName = `REPORTE_DIARIO_${fechaClean}.xlsx`;
        }
        if (!customName.toLowerCase().endsWith('.xlsx')) customName += '.xlsx';

        a.href = url;
        a.download = customName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        if (typeof showMessage === 'function') {
            showMessage(`✅ Reporte Diario generado con éxito (${data.rows.length} filas)`, 'fix-success');
        }

    } catch (err) {
        console.error('Error al generar Excel del Reporte Diario:', err);
        alert('Ocurrió un error al generar el archivo Excel: ' + err.message);
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = originalText;
        }
    }
};

// Renderizar la interfaz visual de la pestaña
window.renderReporteDiarioView = function() {
    const container = document.getElementById('reporteDiarioView');
    if (!container) return;

    // Inicializar inputs de fecha si están vacíos
    const now = new Date();
    const hoyIso = now.toISOString().split('T')[0];

    const dYesterday = new Date(now);
    dYesterday.setDate(now.getDate() - 1);
    const ayerIso = dYesterday.toISOString().split('T')[0];

    const dTomorrow = new Date(now);
    dTomorrow.setDate(now.getDate() + 1);
    const mananaIso = dTomorrow.toISOString().split('T')[0];

    const fHoyEl = document.getElementById('repDiarioFechaHoy');
    const fAyerEl = document.getElementById('repDiarioFechaAyer');
    const fMananaEl = document.getElementById('repDiarioFechaManana');
    const fileNameEl = document.getElementById('repDiarioFileName');

    if (fHoyEl && !fHoyEl.value) fHoyEl.value = hoyIso;
    if (fAyerEl && !fAyerEl.value) fAyerEl.value = ayerIso;
    if (fMananaEl && !fMananaEl.value) fMananaEl.value = mananaIso;

    // Nombre sugerido por defecto: ej REPORTE 22 DE SEPTIEMBRE.xlsx
    if (fileNameEl && !fileNameEl.value) {
        const meses = ['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'];
        fileNameEl.value = `REPORTE ${now.getDate()} DE ${meses[now.getMonth()]}.xlsx`;
    }

    // Obtener datos procesados
    const data = window.buildReporteDiarioData();

    // Actualizar KPIs
    const kpiHoyVisitas = document.getElementById('rdKpiHoyVisitas');
    const kpiHoyEquipos = document.getElementById('rdKpiHoyEquipos');
    const kpiMananaVisitas = document.getElementById('rdKpiMananaVisitas');
    const kpiMananaEquipos = document.getElementById('rdKpiMananaEquipos');
    const kpiTotalFilas = document.getElementById('rdKpiTotalFilas');

    if (kpiHoyVisitas) kpiHoyVisitas.textContent = data.visitasHoyCount;
    if (kpiHoyEquipos) kpiHoyEquipos.textContent = data.equiposHoyCount + ' equipos';
    if (kpiMananaVisitas) kpiMananaVisitas.textContent = data.visitasMananaCount;
    if (kpiMananaEquipos) kpiMananaEquipos.textContent = data.equiposMananaCount + ' equipos';
    if (kpiTotalFilas) kpiTotalFilas.textContent = data.totalFilas;

    // Renderizar tabla de previsualización
    const tbody = document.getElementById('repDiarioTableBody');
    const emptyState = document.getElementById('repDiarioEmptyState');
    const searchFilter = (document.getElementById('repDiarioSearch') ? document.getElementById('repDiarioSearch').value : '').toLowerCase().trim();

    if (!tbody) return;

    if (data.rows.length === 0) {
        tbody.innerHTML = '';
        if (emptyState) emptyState.classList.remove('hidden');
        return;
    }

    if (emptyState) emptyState.classList.add('hidden');

    const filteredRows = data.rows.filter(r => {
        if (!searchFilter) return true;
        const c = r.raw.cliente.toLowerCase();
        const eq = r.raw.equipo.toLowerCase();
        const ser = r.raw.serie.toLowerCase();
        const dir = r.raw.direccion.toLowerCase();
        return c.includes(searchFilter) || eq.includes(searchFilter) || ser.includes(searchFilter) || dir.includes(searchFilter);
    });

    tbody.innerHTML = filteredRows.map((r, index) => {
        const item = r.raw;
        const isHoy = item.isHoy;
        const rowBg = isHoy ? 'bg-white hover:bg-emerald-50/50' : 'bg-blue-50/20 hover:bg-blue-50/50';
        const badgeClass = isHoy 
            ? 'bg-emerald-100 text-emerald-800 border-emerald-300' 
            : 'bg-blue-100 text-blue-800 border-blue-300';
        const serieDisplay = item.serie === 'ABIERTO'
            ? '<span class="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-amber-100 text-amber-800 border border-amber-300">ABIERTO</span>'
            : (item.serie ? `<span class="font-mono font-bold text-stone-900 bg-stone-100 px-1.5 py-0.5 rounded">${item.serie}</span>` : '<span class="text-stone-400 italic text-[11px]">(Sin serie)</span>');

        return `
            <tr class="border-b border-stone-200 transition-colors ${rowBg} text-xs">
                <td class="py-2.5 px-3 font-mono font-bold text-stone-500 text-center">${index + 1}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-mono">${item.fecha_solicitud}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-mono font-bold text-indigo-900">${item.hora_solicitud}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-mono font-bold text-stone-700">${item.fecha_cierre}</td>
                <td class="py-2.5 px-3 font-bold text-stone-800">${item.cliente}</td>
                <td class="py-2.5 px-3 font-medium text-stone-900">${item.equipo}</td>
                <td class="py-2.5 px-3 text-center">${serieDisplay}</td>
                <td class="py-2.5 px-3 text-stone-600 max-w-[180px] truncate" title="${item.direccion}">${item.direccion}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-bold text-stone-700">${item.tecnico}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-mono">${item.fecha_primera_visita}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap font-mono font-black ${isHoy ? 'text-emerald-700' : 'text-blue-700'}">${item.horario_visita}</td>
                <td class="py-2.5 px-3 text-center whitespace-nowrap">
                    <span class="px-2 py-0.5 rounded-full text-[10px] font-black border ${badgeClass}">${item.estado}</span>
                </td>
                <td class="py-2.5 px-3 text-stone-500 max-w-[150px] truncate text-[11px]" title="${item.email}">${item.email || '-'}</td>
            </tr>
        `;
    }).join('');
};

// Acceso rápido para cambiar fechas de reporte
window.setReporteDiarioFechasHoyManana = function() {
    const now = new Date();
    const hoyIso = now.toISOString().split('T')[0];

    const dYesterday = new Date(now);
    dYesterday.setDate(now.getDate() - 1);
    const ayerIso = dYesterday.toISOString().split('T')[0];

    const dTomorrow = new Date(now);
    dTomorrow.setDate(now.getDate() + 1);
    const mananaIso = dTomorrow.toISOString().split('T')[0];

    const fHoyEl = document.getElementById('repDiarioFechaHoy');
    const fAyerEl = document.getElementById('repDiarioFechaAyer');
    const fMananaEl = document.getElementById('repDiarioFechaManana');

    if (fHoyEl) fHoyEl.value = hoyIso;
    if (fAyerEl) fAyerEl.value = ayerIso;
    if (fMananaEl) fMananaEl.value = mananaIso;

    window.renderReporteDiarioView();
};
